<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Write Review | ShopNest</title><link rel="stylesheet" href="style.css"></head><body><?php require __DIR__.'/../layout/header.php'; ?><main class="container cart-page"><div class="panel" style="max-width:600px;margin:50px auto"><h1>Write a Review</h1><p class="muted-text">Product: <?= htmlspecialchars($product['name']) ?></p><?php if($error): ?><p class="error-message"><?= htmlspecialchars($error) ?></p><?php endif; ?><form method="post"><input type="hidden" name="product_id" value="<?= $product['id'] ?>"><div class="field"><label>Rating</label><select name="rating" required><option value="">Select rating</option><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Average</option><option value="2">2 - Poor</option><option value="1">1 - Very Poor</option></select></div><div class="field"><label>Comment</label><textarea name="comment" required></textarea></div><button class="btn btn-primary">Submit Review</button><a class="btn btn-outline" href="product.php?id=<?= $product['id'] ?>">Cancel</a></form></div></main><?php require __DIR__.'/../layout/footer.php'; ?></body></html>
